INSERT INTO modules (id, track_id, title, description, content, points, order_index)
VALUES 
('00000000-0000-0000-0000-0000000000m1', '00000000-0000-0000-0000-000000000001', 'Mindset de Alta Performance', 'Como se preparar mentalmente para o sucesso.', '# Mindset de Alta Performance\n\nO sucesso em vendas começa na mente. Para vender protocolos de alto valor, você precisa acreditar no valor que entrega.\n\n### Pilares do Mindset Roones:\n1. **Foco na Solução**: Não vendemos procedimentos, vendemos transformações.\n2. **Resiliência**: O "não" é apenas um degrau para o "sim".\n3. **Empatia de Luxo**: Entender as dores profundas do cliente premium.', 100, 1),
('00000000-0000-0000-0000-0000000000m2', '00000000-0000-0000-0000-000000000001', 'O Funil de Vendas Roones', 'Entendendo cada etapa da jornada.', '# O Funil de Vendas Roones\n\nO funil de vendas é a espinha dorsal da nossa metodologia. Ele se divide em:\n\n1. **Atração**: Onde o lead conhece a clínica.\n2. **Qualificação**: Entendendo se o lead tem o perfil.\n3. **Apresentação**: Onde o valor é entregue.\n4. **Fechamento**: A assinatura do contrato.\n\nCada etapa exige um tom de voz específico.', 100, 2);
