INSERT INTO modules (id, track_id, title, description, content, points, order_index)
VALUES 
('00000000-0000-0000-0000-0000000000m3', '00000000-0000-0000-0000-000000000002', 'Gatilhos Mentais de Luxo', 'Como usar a psicologia a seu favor.', '# Gatilhos Mentais de Luxo\n\nNo mercado de alto padrão, os gatilhos mentais devem ser sutis e elegantes.\n\n- **Escassez**: Agenda concorrida e exclusividade.\n- **Autoridade**: Resultados comprovados e tecnologia de ponta.\n- **Prova Social**: Depoimentos de clientes satisfeitos (com discrição).', 100, 1),
('00000000-0000-0000-0000-0000000000m4', '00000000-0000-0000-0000-000000000002', 'Contorno de Objeções Real', 'Scripts prontos para as situações mais comuns.', '# Contorno de Objeções\n\nObjeções não são barreiras, são pedidos de mais informação.\n\n### Técnica dos 3 Rs:\n1. **Reconhecer**: Valide o sentimento do cliente.\n2. **Reenquadrar**: Mude a perspectiva de custo para investimento.\n3. **Resolver**: Ofereça a solução definitiva.', 100, 2);
