INSERT INTO modules (id, track_id, title, description, content, points, order_index)
VALUES 
('00000000-0000-0000-0000-00000000iza1', '00000000-0000-0000-0000-000000000005', 'Como Consultar a Iza', 'Extraindo o melhor da sua assistente virtual.', '# Como Consultar a Iza\n\nA Iza foi treinada com toda a metodologia Roones. Você pode:\n\n1. **Pedir Scripts**: "Iza, como respondo a um cliente que disse que vai pensar?"\n2. **Analisar Prints**: Cole o texto de uma conversa e peça análise.\n3. **Treinar Pitch**: Peça para a Iza simular um cliente difícil.', 100, 1),
('00000000-0000-0000-0000-00000000iza2', '00000000-0000-0000-0000-000000000005', 'Análise de Conversas Reais', 'Melhorando sua taxa de conversão com IA.', '# Análise de Conversas\n\nUse a Iza para identificar onde você está perdendo o cliente.\n\n- Cole a conversa.\n- Pergunte: "Onde eu poderia ter sido mais persuasivo?"\n- Aplique a sugestão no próximo lead.', 100, 2);
INSERT INTO modules (id, track_id, title, description, content, video_url, thumbnail, points, order_index)
VALUES 
('00000000-0000-0000-0000-0000000000c1', '00000000-0000-0000-0000-000000000006', 'Estratégias de Fechamento em Clínicas de Luxo', 'Aprenda as técnicas avançadas de fechamento para o mercado de alto padrão.', 'Nesta aula, exploramos como o fechamento em clínicas de luxo difere do mercado tradicional. Focamos em valor, não em preço.', 'https://www.youtube.com/embed/dQw4w9WgXcQ', 'https://picsum.photos/seed/luxury/800/450', 150, 1),
('00000000-0000-0000-0000-0000000000c2', '00000000-0000-0000-0000-000000000006', 'Psicologia do Consumidor de Alto Padrão', 'Entenda o que motiva a decisão de compra do cliente premium.', 'Entender a psicologia por trás da compra de serviços de alto valor é fundamental para criar conexão real.', 'https://www.youtube.com/embed/dQw4w9WgXcQ', 'https://picsum.photos/seed/psychology/800/450', 150, 2),
('00000000-0000-0000-0000-0000000000c3', '00000000-0000-0000-0000-000000000006', 'O Método Roones de Encantamento', 'Como transformar uma consulta em uma experiência memorável.', 'O encantamento começa antes do cliente entrar na clínica. Aprenda o passo a passo da recepção ao pós-venda.', 'https://www.youtube.com/embed/dQw4w9WgXcQ', 'https://picsum.photos/seed/experience/800/450', 150, 3);
INSERT INTO quiz_questions (id, module_id, question, options, correct_option_index)
VALUES 
('00000000-0000-0000-0000-000000000cq1', '00000000-0000-0000-0000-0000000000c1', 'Qual é o principal diferencial do fechamento no mercado de luxo?', '["Foco apenas no preço", "Experiência e valor percebido", "Velocidade extrema"]'::jsonb, 1),
('00000000-0000-0000-0000-000000000cq2', '00000000-0000-0000-0000-0000000000c2', 'O que o cliente de alto padrão mais valoriza?', '["Descontos agressivos", "Exclusividade e segurança", "Brindes genéricos"]'::jsonb, 1);
INSERT INTO objections (id, trigger, reason, expert_view, rapport_response, consultative_response, authority_response, response)
VALUES 
('00000000-0000-0000-0000-000000000001', 'Está caro', 'O cliente sente que o valor financeiro é maior do que o benefício percebido no momento.', 'O Especialista entende que o cliente ainda compara custo porque não visualizou a transformação real. O foco deve ser elevar a percepção de valor antes de falar de preço.', 'Entendo perfeitamente, {nome}. Quando falamos de um procedimento que envolve sua autoestima e saúde, o investimento é algo que realmente precisamos olhar com cuidado. Me conta, além do valor, existe algo mais que te deixou em dúvida?', 'Compreendo sua preocupação. Geralmente, quando um paciente sente que o valor está alto, é porque talvez eu não tenha deixado claro como esse protocolo vai resolver especificamente aquela queixa que você me trouxe sobre {queixa}. Faz sentido para você?', 'Eu entendo. Na Roones, não trabalhamos com "preço", mas com protocolos de alta performance. O valor reflete a segurança de um resultado previsível e a tecnologia de ponta que utilizamos. Você prefere priorizar o menor custo ou o melhor resultado para o seu rosto?', 'Entendo perfeitamente. Quando um paciente diz que está caro, geralmente é porque ele ainda não percebeu o valor total da transformação que entregamos. O foco deve ser reenquadrar o custo como investimento em autoestima e segurança.'),
('00000000-0000-0000-0000-000000000002', 'Vou falar com meu marido/esposa', 'Uso de um terceiro como barreira para a decisão ou necessidade real de consenso familiar.', 'Esta objeção muitas vezes esconde um medo pessoal ou falta de autoridade na decisão. Devemos validar o consenso mas reforçar o desejo da paciente.', 'É ótimo que você queira compartilhar essa decisão! Afinal, uma mudança na autoestima reflete em toda a família. O que você acha de levarmos essa proposta para ele(a) juntos?', 'Com certeza, é uma decisão importante. No entanto, muitas vezes quem não participou da nossa consulta não consegue visualizar a transformação que planejamos aqui hoje. O que você acha de eu te enviar um material exclusivo que explica exatamente o que vamos conquistar?', 'Respeito muito o consenso familiar. Mas me diga, se a decisão dependesse apenas de você hoje, você iniciaria o protocolo? Se sim, vamos focar em como apresentar isso para ele(a) da melhor forma.', 'É ótimo que você queira compartilhar essa decisão. No entanto, muitas vezes quem não participou da consulta não consegue visualizar a transformação real. O ideal é focar no seu desejo e em como isso impactará positivamente sua vida.'),
('00000000-0000-0000-0000-000000000003', 'Tenho medo de não ficar natural', 'Receio de resultados artificiais, exagerados ou que descaracterizem o rosto.', 'O cliente premium tem pavor da "estetização" exagerada. A segurança vem da prova de naturalidade e da filosofia da clínica.', 'Esse é o receio de 90% das nossas clientes mais sofisticadas, e é exatamente por isso que elas escolhem a Roones. Nossa filosofia é realçar sua beleza, não te transformar.', 'Eu entendo. Na verdade, o "natural" é a nossa assinatura. Trabalhamos com micro-doses e pontos estratégicos. Veja esses casos de antes e depois de clientes que tinham o mesmo receio que você...', 'Na Roones, seguimos a regra de ouro da estética: menos é mais. Utilizamos tecnologia que estimula seu próprio colágeno. O resultado é você, só que na sua melhor versão de 10 anos atrás.', 'Esse é um receio comum. Na Roones, nossa filosofia é a "Beleza Inteligente": realçar o que você já tem de melhor sem transformar seu rosto, garantindo um aspecto sempre natural e descansado.'),
('00000000-0000-0000-0000-000000000004', 'Vou pensar', 'Insegurança ou falta de clareza sobre o próximo passo, muitas vezes mascarada como necessidade de tempo.', 'O "vou pensar" é quase sempre uma cortina de fumaça para uma dúvida não sanada ou medo do investimento. O objetivo é descobrir o que falta para a decisão.', 'Claro, {nome}, é uma decisão importante e você deve estar segura. Geralmente, quando meus pacientes precisam "pensar", é porque ou algo no plano não ficou claro, ou o financeiro precisa de um ajuste. Qual dos dois é o seu caso?', 'Respeito muito seu tempo de decisão. Para eu te ajudar melhor, o que exatamente você precisa analisar que ainda não cobrimos aqui? Se for algo técnico, podemos sanar agora.', 'Com certeza. Só lembrando que nossa agenda para este protocolo específico está com alta procura devido aos resultados da última semana. Se pensarmos em fechar hoje, consigo garantir sua vaga na próxima quinzena. O que te impede de começarmos agora?', 'Claro, é uma decisão importante. Geralmente, quando alguém precisa pensar, é por um de dois motivos: ou não se sentiu seguro com o tratamento, ou o investimento está fora do planejado agora. Qual dos dois é o seu caso?');
